/* active mask (set by paint_node, consumed by the fill_* emitters):
 * linear-gradient alpha mask over the owner box (in-box px). mask_quad
 * holds the per-corner mask alpha (TL,TR,BL,BR); active flags presence. */
struct MaskActive
{
    bool active;
    int bx, by, bw, bh;
    float m[4];
};
static std::vector<MaskActive> g_mask_stack;

/* active clip-path (set by paint_node, consumed by the fill_* emitters):
 * shape in the owner's in-box px + the owner box in framebuffer coords
 * (for mapping onto each emitted quad). Stacked (nested clip-paths
 * intersect). CPU path uses the framebuffer-space rect/circle directly. */
struct ClipPathActive
{
    ClipPath shape;
    int bx, by, bw, bh;
};
static std::vector<ClipPathActive> g_clip_stack;

/* map the active clip shape onto one emitted quad (qx,qy,qw,qh, framebuffer
 * coords): center into quad-local coords, half-size/radii unchanged
 * (same scale). Returns the type (0 = none). */
static int clip_for_quad(float qx, float qy, float* ccx, float* ccy,
                         float* cr0, float* cr1, float* crad)
{
    if (g_clip_stack.empty()) {
        return 0;
    }
    const ClipPathActive& top = g_clip_stack.back();
    if (top.shape.type <= 0) {
        return 0;
    }
    *ccx = static_cast<float>(top.bx) + top.shape.ccx - qx;
    *ccy = static_cast<float>(top.by) + top.shape.ccy - qy;
    *cr0 = top.shape.cr0;
    *cr1 = top.shape.cr1;
    *crad = top.shape.crad;
    return top.shape.type;
}

/* mask-image queries for other TUs (render_color.cpp's fill_gradient):
 * the stack lives here (static), so these non-static accessors expose it.
 * mask_at() samples the top mask at a framebuffer point (1 = no mask). */
bool whaleui_mask_active()
{
    return !g_mask_stack.empty() && g_mask_stack.back().active;
}
/* clip-path stack query for other TUs (render_text.cpp's blit loop):
 * true while any shape is pushed (nested shapes intersect). */
bool whaleui_clip_active()
{
    return !g_clip_stack.empty();
}
float whaleui_mask_at(float fx, float fy)
{
    if (g_mask_stack.empty() || !g_mask_stack.back().active) {
        return 1.0f;
    }
    const MaskActive& mk = g_mask_stack.back();
    float bw = mk.bw > 0 ? static_cast<float>(mk.bw) : 1.0f;
    float bh = mk.bh > 0 ? static_cast<float>(mk.bh) : 1.0f;
    float u = (fx - static_cast<float>(mk.bx)) / bw;
    float v = (fy - static_cast<float>(mk.by)) / bh;
    if (u < 0) {
        u = 0;
    } else if (u > 1) {
        u = 1;
    }
    if (v < 0) {
        v = 0;
    } else if (v > 1) {
        v = 1;
    }
    return mk.m[0] * (1 - u) * (1 - v) + mk.m[1] * u * (1 - v) +
           mk.m[2] * (1 - u) * v + mk.m[3] * u * v;
}
/* corner mask values for one emitted quad (TL,TR,BL,BR, framebuffer) */
static void mask_corners(float x, float y, float w, float h, float out[4])
{
    out[0] = whaleui_mask_at(x, y);
    out[1] = whaleui_mask_at(x + w, y);
    out[2] = whaleui_mask_at(x, y + h);
    out[3] = whaleui_mask_at(x + w, y + h);
}
/* scale one 0xAARRGGBB color's alpha by mv (0..1) */
unsigned int whaleui_mask_tint(unsigned int c, float mv)
{
    unsigned int a = (c >> 24) & 0xFF;
    unsigned int ma = static_cast<unsigned int>(a * mv + 0.5f);
    return (ma << 24) | (c & 0x00FFFFFF);
}
/* project a linear Gradient's alpha onto the box corners (in-box px): the
 * same axis projection fill_gradient uses, so the mask matches the
 * equivalent background gradient exactly. */
static void mask_from_linear(const Gradient& mg, int bw, int bh, float m[4])
{
    const float PI_F = 3.14159265358979f;
    float rad = mg.angle_deg * PI_F / 180.0f;
    float ddx = std::sin(rad), ddy = -std::cos(rad);
    float ccx = bw * 0.5f, ccy = bh * 0.5f;
    float px[4] = {0, static_cast<float>(bw), 0, static_cast<float>(bw)};
    float py[4] = {0, 0, static_cast<float>(bh), static_cast<float>(bh)};
    float t[4], t0 = 1e30f, t1 = -1e30f;
    for (int i = 0; i < 4; ++i) {
        t[i] = (px[i] - ccx) * ddx + (py[i] - ccy) * ddy;
        if (t[i] < t0) {
            t0 = t[i];
        }
        if (t[i] > t1) {
            t1 = t[i];
        }
    }
    float span = t1 - t0;
    if (span <= 0.0f) {
        span = 1.0f;
    }
    for (int i = 0; i < 4; ++i) {
        unsigned int c = grad_color(mg, (t[i] - t0) / span);
        m[i] = static_cast<float>((c >> 24) & 0xFF) / 255.0f;
    }
}

void dirty_rect(int x0, int y0, int x1, int y1, Clip* out)
{
    if (!out) {
        return;
    }
    if (out->w <= 0 || out->h <= 0) {
        out->x = x0;
        out->y = y0;
        out->w = x1 - x0;
        out->h = y1 - y0;
        return;
    }
    int ax0 = out->x < x0 ? out->x : x0;
    int ay0 = out->y < y0 ? out->y : y0;
    int ax1 = (out->x + out->w) > x1 ? (out->x + out->w) : x1;
    int ay1 = (out->y + out->h) > y1 ? (out->y + out->h) : y1;
    out->x = ax0;
    out->y = ay0;
    out->w = ax1 - ax0;
    out->h = ay1 - ay0;
}

void clip_rect(int& x0, int& y0, int& x1, int& y1, const Clip* clip)
{
    if (!clip || clip->w <= 0 || clip->h <= 0) {
        return;
    }
    int cx0 = clip->x, cy0 = clip->y;
    int cx1 = clip->x + clip->w, cy1 = clip->y + clip->h;
    if (x0 < cx0) { x0 = cx0; }
    if (y0 < cy0) { y0 = cy0; }
    if (x1 > cx1) { x1 = cx1; }
    if (y1 > cy1) { y1 = cy1; }
}

void fill_rect(std::vector<unsigned int>& fb, int fbw, int fbh,
               int x, int y, int w, int h, unsigned int color, const Clip* clip)
{
    /* mask: modulate the color alpha by the mask value at the quad
     * corners (bilinear over the emitted quad; exact for linear-gradient
     * masks). CPU path multiplies per pixel below. */
    unsigned int mcols[6];
    bool has_mask = false;
    if (!g_mask_stack.empty() && g_mask_stack.back().active) {
        float mv[4];
        mask_corners(static_cast<float>(x), static_cast<float>(y),
                     static_cast<float>(w), static_cast<float>(h), mv);
        /* v[0]=TL v[1]=TR v[2]=BL v[3]=TR v[4]=BL v[5]=BR */
        unsigned int base_a = (color >> 24) & 0xFF;
        unsigned int mc[4];
        for (int k = 0; k < 4; ++k) {
            unsigned int ma =
                static_cast<unsigned int>(base_a * mv[k] + 0.5f);
            mc[k] = (ma << 24) | (color & 0x00FFFFFF);
        }
        mcols[0] = mc[0];
        mcols[1] = mc[1];
        mcols[2] = mc[2];
        mcols[3] = mc[1];
        mcols[4] = mc[2];
        mcols[5] = mc[3];
        has_mask = true;
    }
    if (g_gpu) {
        int c[4];
        const int* cp = nullptr;
        if (clip) {
            c[0] = clip->x;
            c[1] = clip->y;
            c[2] = clip->w;
            c[3] = clip->h;
            cp = c;
        }
        float ct = 0, ccx = 0, ccy = 0, cr0 = 0, cr1 = 0, crad = 0;
        if (!g_clip_stack.empty()) {
            ct = static_cast<float>(clip_for_quad(static_cast<float>(x),
                                                  static_cast<float>(y), &ccx,
                                                  &ccy, &cr0, &cr1, &crad));
        }
        if (has_mask) {
            /* masked solid = four corner colors (same rgb, per-corner
             * alpha): reuse the gradient rect (free rasterizer interp) */
            float mct = 0, mccx = 0, mccy = 0, mcr0 = 0, mcr1 = 0, mcrad = 0;
            if (!g_clip_stack.empty()) {
                mct = static_cast<float>(clip_for_quad(
                    static_cast<float>(x), static_cast<float>(y), &mccx,
                    &mccy, &mcr0, &mcr1, &mcrad));
            }
            whaleui_gpu_gradient_rect(g_gpu, static_cast<float>(x),
                                      static_cast<float>(y),
                                      static_cast<float>(w),
                                      static_cast<float>(h), mcols[0],
                                      mcols[1], mcols[2], mcols[5], cp, mct,
                                      mccx, mccy, mcr0, mcr1, mcrad);
        } else {
            whaleui_gpu_rect(g_gpu, static_cast<float>(x),
                             static_cast<float>(y), static_cast<float>(w),
                             static_cast<float>(h), 0.0f, color, cp, ct, ccx,
                             ccy, cr0, cr1, crad);
        }
        return;
    }
    if (w <= 0 || h <= 0) {
        return;
    }
    int x0 = x < 0 ? 0 : x;
    int y0 = y < 0 ? 0 : y;
    int x1 = x + w > fbw ? fbw : x + w;
    int y1 = y + h > fbh ? fbh : y + h;
    clip_rect(x0, y0, x1, y1, clip);
    unsigned int a = (color >> 24) & 0xFF;
    if (a == 0 || x1 <= x0 || y1 <= y0) {
        return;
    }
    if (a == 255) {
        if (g_clip_stack.empty() && !has_mask) {
            for (int yy = y0; yy < y1; ++yy) {
                std::fill(fb.begin() + static_cast<size_t>(yy) * fbw + x0,
                          fb.begin() + static_cast<size_t>(yy) * fbw + x1, color);
            }
            return;
        }
        for (int yy = y0; yy < y1; ++yy) {
            for (int xx = x0; xx < x1; ++xx) {
                if (!inside_clip(xx, yy)) {
                    continue;
                }
                if (has_mask) {
                    float mv = whaleui_mask_at(static_cast<float>(xx),
                                               static_cast<float>(yy));
                    if (mv <= 0.0f) {
                        continue;
                    }
                    if (mv < 1.0f) {
                        /* opaque source faded by the mask: dst shows
                         * through the transparent part */
                        unsigned int& d =
                            fb[static_cast<size_t>(yy) * fbw + xx];
                        unsigned int dr = (d >> 16) & 0xFF,
                                     dg = (d >> 8) & 0xFF, db = d & 0xFF;
                        unsigned int sr = (color >> 16) & 0xFF,
                                     sg = (color >> 8) & 0xFF,
                                     sb = color & 0xFF;
                        unsigned int ma = static_cast<unsigned int>(255 * mv +
                                                                    0.5f);
                        unsigned int nr =
                            (sr * ma + dr * (255 - ma)) / 255;
                        unsigned int ng =
                            (sg * ma + dg * (255 - ma)) / 255;
                        unsigned int nb =
                            (sb * ma + db * (255 - ma)) / 255;
                        d = 0xFF000000 | (nr << 16) | (ng << 8) | nb;
                        continue;
                    }
                }
                fb[static_cast<size_t>(yy) * fbw + xx] = color;
            }
        }
        return;
    }
    unsigned int r = (color >> 16) & 0xFF, g = (color >> 8) & 0xFF, b = color & 0xFF;
    /* mask modulation on the CPU path (per pixel) */
    bool cpu_mask = has_mask;
    for (int yy = y0; yy < y1; ++yy) {
        for (int xx = x0; xx < x1; ++xx) {
            if (!inside_clip(xx, yy)) {
                continue;
            }
            unsigned int use_a = a;
            if (cpu_mask) {
                float mv = whaleui_mask_at(static_cast<float>(xx),
                                           static_cast<float>(yy));
                use_a = static_cast<unsigned int>(a * mv + 0.5f);
                if (use_a == 0) {
                    continue;
                }
            }
            unsigned int& d = fb[static_cast<size_t>(yy) * fbw + xx];
            unsigned int dr = (d >> 16) & 0xFF, dg = (d >> 8) & 0xFF, db = d & 0xFF;
            unsigned int nr = (r * use_a + dr * (255 - use_a)) / 255;
            unsigned int ng = (g * use_a + dg * (255 - use_a)) / 255;
            unsigned int nb = (b * use_a + db * (255 - use_a)) / 255;
            d = 0xFF000000 | (nr << 16) | (ng << 8) | nb;
        }
    }
}

bool inside_rounded(int px, int py, int x, int y, int w, int h, int radius)
{
    if (w <= 0 || h <= 0) {
        return false;
    }
    if (radius <= 0) {
        return px >= x && px < x + w && py >= y && py < y + h;
    }
    long dx = 0, dy = 0;
    if (px < x + radius) {
        dx = static_cast<long>(x + radius - px);
    } else if (px >= x + w - radius) {
        dx = static_cast<long>(px - (x + w - radius)) + 1;
    }
    if (py < y + radius) {
        dy = static_cast<long>(y + radius - py);
    } else if (py >= y + h - radius) {
        dy = static_cast<long>(py - (y + h - radius)) + 1;
    }
    if (dx != 0 || dy != 0) {
        long r2 = static_cast<long>(radius) * radius;
        return dx * dx + dy * dy <= r2;
    }
    return true; /* in the middle band */
}

/* CPU mirror of the clip-path SDF (framebuffer coords): the active shape
 * (if any) must contain (px,py). Rounded inset rect / circle / ellipse. */
bool inside_clip(int px, int py)
{
    if (g_clip_stack.empty()) {
        return true;
    }
    const ClipPathActive& top = g_clip_stack.back();
    const ClipPath& s = top.shape;
    if (s.type <= 0) {
        return true;
    }
    float ccx = static_cast<float>(top.bx) + s.ccx;
    float ccy = static_cast<float>(top.by) + s.ccy;
    if (s.type == 1) {
        /* inset rounded rect */
        float dx = 0, dy = 0;
        float x0 = ccx - s.cr0, x1 = ccx + s.cr0;
        float y0 = ccy - s.cr1, y1 = ccy + s.cr1;
        float rr = s.crad;
        if (rr > 0) {
            if (px < x0 + rr) {
                dx = x0 + rr - px;
            } else if (px >= x1 - rr) {
                dx = px - (x1 - rr) + 1;
            }
            if (py < y0 + rr) {
                dy = y0 + rr - py;
            } else if (py >= y1 - rr) {
                dy = py - (y1 - rr) + 1;
            }
            if (dx != 0 || dy != 0) {
                return dx * dx + dy * dy <= rr * rr;
            }
            return true;
        }
        return px >= x0 && px < x1 && py >= y0 && py < y1;
    }
    if (s.type == 2) {
        float dx = px - ccx, dy = py - ccy;
        return dx * dx + dy * dy <= s.cr0 * s.cr0;
    }
    /* ellipse: normalized distance <= 1 */
    if (s.cr0 <= 0 || s.cr1 <= 0) {
        return false;
    }
    float nx = (px - ccx) / s.cr0, ny = (py - ccy) / s.cr1;
    return nx * nx + ny * ny <= 1.0f;
}

void fill_round_rect(std::vector<unsigned int>& fb, int fbw, int fbh,
                     int x, int y, int w, int h, int radius,
                     unsigned int color, const Clip* clip)
{
    /* mask: same per-corner alpha trick as fill_rect (masked solid =
     * four corner colors through the gradient rect, exact for linear
     * masks). Computed up front so both the GPU and CPU paths share it. */
    bool has_mask = whaleui_mask_active();
    unsigned int mcols[4] = {color, color, color, color};
    if (has_mask) {
        float mv[4];
        mask_corners(static_cast<float>(x), static_cast<float>(y),
                     static_cast<float>(w), static_cast<float>(h), mv);
        for (int k = 0; k < 4; ++k) {
            mcols[k] = whaleui_mask_tint(color, mv[k]);
        }
    }
    if (g_gpu) {
        int c[4];
        const int* cp = nullptr;
        if (clip) {
            c[0] = clip->x;
            c[1] = clip->y;
            c[2] = clip->w;
            c[3] = clip->h;
            cp = c;
        }
        float ct = 0, ccx = 0, ccy = 0, cr0 = 0, cr1 = 0, crad = 0;
        if (!g_clip_stack.empty()) {
            ct = static_cast<float>(clip_for_quad(static_cast<float>(x),
                                                  static_cast<float>(y), &ccx,
                                                  &ccy, &cr0, &cr1, &crad));
        }
        if (has_mask) {
            /* masked rounded rect in ONE draw: per-corner mask alpha
             * through the gradient rect + the real corner radius (the
             * SDF and the interpolated alpha multiply in the shader) */
            whaleui_gpu_gradient_rect(
                g_gpu, static_cast<float>(x), static_cast<float>(y),
                static_cast<float>(w), static_cast<float>(h), mcols[0],
                mcols[1], mcols[2], mcols[3], cp, ct, ccx, ccy, cr0, cr1,
                crad, static_cast<float>(radius));
            return;
        }
        whaleui_gpu_rect(g_gpu, static_cast<float>(x), static_cast<float>(y),
                         static_cast<float>(w), static_cast<float>(h),
                         static_cast<float>(radius), color, cp, ct, ccx, ccy,
                         cr0, cr1, crad);
        return;
    }
    if (radius <= 0) {
        fill_rect(fb, fbw, fbh, x, y, w, h, color, clip);
        return;
    }
    int half = w < h ? w / 2 : h / 2;
    if (radius > half) {
        radius = half;
    }
    int x0 = x < 0 ? 0 : x;
    int y0 = y < 0 ? 0 : y;
    int x1 = x + w > fbw ? fbw : x + w;
    int y1 = y + h > fbh ? fbh : y + h;
    clip_rect(x0, y0, x1, y1, clip);
    unsigned int a = (color >> 24) & 0xFF;
    if (a == 0 || x1 <= x0 || y1 <= y0) {
        return;
    }
    unsigned int r = (color >> 16) & 0xFF, g = (color >> 8) & 0xFF, b = color & 0xFF;
    bool cpu_mask = has_mask;
    for (int yy = y0; yy < y1; ++yy) {
        for (int xx = x0; xx < x1; ++xx) {
            if (!inside_rounded(xx, yy, x, y, w, h, radius)) {
                continue; /* outside the rounded corner */
            }
            if (!inside_clip(xx, yy)) {
                continue; /* outside the clip-path shape */
            }
            unsigned int use_a = a;
            if (cpu_mask) {
                float mv = whaleui_mask_at(static_cast<float>(xx),
                                           static_cast<float>(yy));
                use_a = static_cast<unsigned int>(a * mv + 0.5f);
                if (use_a == 0) {
                    continue;
                }
            }
            unsigned int& d = fb[static_cast<size_t>(yy) * fbw + xx];
            unsigned int dr = (d >> 16) & 0xFF, dg = (d >> 8) & 0xFF, db = d & 0xFF;
            if (use_a == 255) {
                d = 0xFF000000 | (r << 16) | (g << 8) | b;
            } else {
                unsigned int nr = (r * use_a + dr * (255 - use_a)) / 255;
                unsigned int ng = (g * use_a + dg * (255 - use_a)) / 255;
                unsigned int nb = (b * use_a + db * (255 - use_a)) / 255;
                d = 0xFF000000 | (nr << 16) | (ng << 8) | nb;
            }
        }
    }
}

/* fill a box rotated by rot_deg degrees (CSS rotate, clockwise) around
 * the (ox, oy) in-box anchor. GPU path: the rasterizer rotates
 * (whaleui_gpu_rect_rot). CPU fallback: the unrotated box (the software
 * path has no rotated rasterizer; parity with pre-rotate builds, never
 * worse). */
void fill_rot_rect(std::vector<unsigned int>& fb, int fbw, int fbh,
                   int x, int y, int w, int h, int radius,
                   unsigned int color, float rot_deg, const Clip* clip,
                   float ox, float oy, float skx, float sky)
{
    if (g_gpu) {
        float ax = static_cast<float>(x) + ox;
        float ay = static_cast<float>(y) + oy;
        float ct = 0, ccx = 0, ccy = 0, cr0 = 0, cr1 = 0, crad = 0;
        if (!g_clip_stack.empty()) {
            ct = static_cast<float>(clip_for_quad(static_cast<float>(x),
                                                  static_cast<float>(y), &ccx,
                                                  &ccy, &cr0, &cr1, &crad));
        }
        whaleui_gpu_rect_rot(g_gpu, static_cast<float>(x),
                             static_cast<float>(y), static_cast<float>(w),
                             static_cast<float>(h), static_cast<float>(radius),
                             color, rot_deg, nullptr, ax, ay, skx, sky,
                             ct, ccx, ccy, cr0, cr1, crad);
        return;
    }
    if (radius > 0) {
        fill_round_rect(fb, fbw, fbh, x, y, w, h, radius, color, clip);
    } else {
        fill_rect(fb, fbw, fbh, x, y, w, h, color, clip);
    }
}

void fill_round_border(std::vector<unsigned int>& fb, int fbw, int fbh,
                       int x, int y, int w, int h, int radius, int bw,
                       unsigned int color, unsigned int bg, const Clip* clip)
{
    if (g_gpu) {
        /* ring via two rounded rects: outer in the border color, then the
         * inner rect re-filled with the element's background color */
        fill_round_rect(fb, fbw, fbh, x, y, w, h, radius, color, clip);
        int ix = x + bw, iy = y + bw, iw = w - 2 * bw, ih = h - 2 * bw;
        int irad = radius - bw;
        if (irad < 0) {
            irad = 0;
        }
        fill_round_rect(fb, fbw, fbh, ix, iy, iw, ih, irad, bg, clip);
        return;
    }
    if (bw <= 0) {
        return;
    }
    if (radius <= 0) {
        fill_rect(fb, fbw, fbh, x, y, w, bw, color, clip);               /* top */
        fill_rect(fb, fbw, fbh, x, y + h - bw, w, bw, color, clip);      /* bottom */
        fill_rect(fb, fbw, fbh, x + w - bw, y, bw, h, color, clip);      /* right */
        fill_rect(fb, fbw, fbh, x, y, bw, h, color, clip);               /* left */
        return;
    }
    int half = w < h ? w / 2 : h / 2;
    if (radius > half) {
        radius = half;
    }
    int ix = x + bw, iy = y + bw, iw = w - 2 * bw, ih = h - 2 * bw;
    int irad = radius - bw;
    if (irad < 0) {
        irad = 0;
    }
    int x0 = x < 0 ? 0 : x;
    int y0 = y < 0 ? 0 : y;
    int x1 = x + w > fbw ? fbw : x + w;
    int y1 = y + h > fbh ? fbh : y + h;
    clip_rect(x0, y0, x1, y1, clip);
    unsigned int a = (color >> 24) & 0xFF;
    if (a == 0 || x1 <= x0 || y1 <= y0) {
        return;
    }
    unsigned int r = (color >> 16) & 0xFF, g = (color >> 8) & 0xFF, b = color & 0xFF;
    for (int yy = y0; yy < y1; ++yy) {
        for (int xx = x0; xx < x1; ++xx) {
            if (!inside_rounded(xx, yy, x, y, w, h, radius)) {
                continue; /* outside the outer rounded rect */
            }
            if (inside_rounded(xx, yy, ix, iy, iw, ih, irad)) {
                continue; /* inside the inner rect: that is the fill area */
            }
            unsigned int& d = fb[static_cast<size_t>(yy) * fbw + xx];
            unsigned int dr = (d >> 16) & 0xFF, dg = (d >> 8) & 0xFF, db = d & 0xFF;
            if (a == 255) {
                d = color;
            } else {
                unsigned int nr = (r * a + dr * (255 - a)) / 255;
                unsigned int ng = (g * a + dg * (255 - a)) / 255;
                unsigned int nb = (b * a + db * (255 - a)) / 255;
                d = 0xFF000000 | (nr << 16) | (ng << 8) | nb;
            }
        }
    }
}

void blend_surface(std::vector<unsigned int>& fb, int fbw, int fbh,
                   const SDL_Surface* surf, int dx, int dy, const Clip* clip,
                   const unsigned int* tint)
{
    if (!surf || !surf->pixels) {
        return;
    }
    const unsigned char* src = static_cast<const unsigned char*>(surf->pixels);
    int pitch = surf->pitch;
    unsigned int tr = tint ? (*tint >> 16) & 0xFF : 0;
    unsigned int tg = tint ? (*tint >> 8) & 0xFF : 0;
    unsigned int tb = tint ? *tint & 0xFF : 0;
    /* mask-image over <img>/glyph blits: the mask alpha scales the source
     * alpha per pixel. needs_clip gates the per-pixel inside_clip() check
     * (off by default: glyph blits are the hottest path in the renderer). */
    bool use_mask = whaleui_mask_active();
    bool needs_clip = use_mask || !g_clip_stack.empty();
    for (int y = 0; y < surf->h; ++y) {
        int ty = dy + y;
        if (ty < 0 || ty >= fbh) {
            continue;
        }
        if (clip && (ty < clip->y || ty >= clip->y + clip->h)) {
            continue;
        }
        if (!inside_clip(dx, ty) && !inside_clip(dx + surf->w - 1, ty)) {
            /* row span outside a circle/ellipse clip: still scan (the
             * per-pixel check below stays exact), no early-out here */
            (void)0;
        }
        for (int x = 0; x < surf->w; ++x) {
            int tx = dx + x;
            if (tx < 0 || tx >= fbw) {
                continue;
            }
            if (clip && (tx < clip->x || tx >= clip->x + clip->w)) {
                continue;
            }
            if (needs_clip && !inside_clip(tx, ty)) {
                continue;
            }
            const unsigned char* s = src + static_cast<size_t>(y) * pitch + static_cast<size_t>(x) * 4;
            unsigned int a = s[3];
            if (a == 0) {
                continue;
            }
            if (use_mask) {
                float mv = whaleui_mask_at(static_cast<float>(tx),
                                           static_cast<float>(ty));
                if (mv <= 0.0f) {
                    continue;
                }
                a = static_cast<unsigned int>(a * mv + 0.5f);
                if (a == 0) {
                    continue;
                }
            }
            unsigned int sr = tint ? tr : s[0];
            unsigned int sg = tint ? tg : s[1];
            unsigned int sb = tint ? tb : s[2];
            unsigned int& d = fb[static_cast<size_t>(ty) * fbw + tx];
            if (a == 255) {
                /* opaque: no blending math (hot path for anti-aliased
                 * glyph cores; text is the biggest per-frame cost) */
                d = 0xFF000000 | (sr << 16) | (sg << 8) | sb;
                continue;
            }
            unsigned int dr = (d >> 16) & 0xFF, dg = (d >> 8) & 0xFF, db = d & 0xFF;
            unsigned int nr = (sr * a + dr * (255 - a)) / 255;
            unsigned int ng = (sg * a + dg * (255 - a)) / 255;
            unsigned int nb = (sb * a + db * (255 - a)) / 255;
            d = 0xFF000000 | (nr << 16) | (ng << 8) | nb;
        }
    }
}

/* one background-size component: "auto" keeps the box size, "%" resolves
 * against it, anything else is px */
float bg_len_px(const std::string& v, int base)
{
    if (v.empty() || v == "auto") {
        return static_cast<float>(base);
    }
    if (v[v.size() - 1] == '%') {
        return std::strtof(v.c_str(), nullptr) * base / 100.0f;
    }
    return std::strtof(v.c_str(), nullptr);
}

/* one background-position component (keyword, % or px). A percentage
 * offsets by (box - tile) like the spec, so "100%" is the right/bottom
 * edge rather than the box width. */
float bg_pos_px(const std::string& v, int base, float tile)
{
    if (v == "center") {
        return (static_cast<float>(base) - tile) / 2.0f;
    }
    if (v == "right" || v == "bottom") {
        return static_cast<float>(base) - tile;
    }
    if (v == "left" || v == "top") {
        return 0;
    }
    if (!v.empty() && v[v.size() - 1] == '%') {
        return (static_cast<float>(base) - tile) *
               std::strtof(v.c_str(), nullptr) / 100.0f;
    }
    return std::strtof(v.c_str(), nullptr);
}

int parse_shadow(const std::string& v, int& ox, int& oy, int& blur,
                 unsigned int& col, int* spread)
{
    ox = oy = blur = 0;
    col = 0;
    if (spread) {
        *spread = 0;
    }
    std::vector<std::string> tok;
    const char* p = v.c_str();
    while (*p) {
        while (*p == ' ' || *p == '\t') {
            ++p;
        }
        if (!*p) {
            break;
        }
        const char* s = p;
        while (*p && *p != ' ' && *p != '\t') {
            ++p;
        }
        tok.emplace_back(s, static_cast<size_t>(p - s));
    }
    int nums[4] = {0, 0, 0, 0};
    size_t ni = 0;
    std::string colstr;
    for (size_t i = 0; i < tok.size(); ++i) {
        const std::string& t = tok[i];
        if (ni < 4 && !t.empty() &&
            (t[0] == '-' || (t[0] >= '0' && t[0] <= '9'))) {
            nums[ni++] = std::atoi(t.c_str());
        } else if (!colstr.empty()) {
            colstr += ' ';
            colstr += t;
        } else {
            colstr = t;
        }
    }
    ox = nums[0];
    oy = nums[1];
    blur = nums[2];
    if (spread) {
        *spread = nums[3];
    }
    /* blur 0 is legal and common: "0 0 0 3px rgba(...)" is how the themes
     * write a focus ring */
    if (colstr.empty()) {
        return -1;
    }
    return whaleui_render_parse_color(colstr.c_str(), &col);
}

int parse_shadow_any(const std::string& v, int& ox, int& oy, int& blur,
                     unsigned int& col)
{
    int rc = parse_shadow(v, ox, oy, blur, col);
    if (rc != 0) {
        /* retry allowing zero blur: split tokens and treat the color as
         * the last token */
        std::vector<std::string> tok;
        const char* p = v.c_str();
        while (*p) {
            while (*p == ' ' || *p == '\t') {
                ++p;
            }
            if (!*p) {
                break;
            }
            const char* s = p;
            while (*p && *p != ' ' && *p != '\t') {
                ++p;
            }
            tok.emplace_back(s, static_cast<size_t>(p - s));
        }
        ox = oy = blur = 0;
        col = 0;
        int nums[2] = {0, 0};
        size_t ni = 0;
        std::string colstr;
        for (size_t i = 0; i < tok.size(); ++i) {
            const std::string& t = tok[i];
            if (ni < 2 && !t.empty() &&
                (t[0] == '-' || (t[0] >= '0' && t[0] <= '9'))) {
                nums[ni++] = std::atoi(t.c_str());
            } else if (!colstr.empty()) {
                colstr += ' ';
                colstr += t;
            } else {
                colstr = t;
            }
        }
        ox = nums[0];
        oy = nums[1];
        if (colstr.empty()) {
            return -1;
        }
        return whaleui_render_parse_color(colstr.c_str(), &col);
    }
    return rc;
}

std::vector<std::string> split_space2(const std::string& v)
{
    std::vector<std::string> out;
    const char* p = v.c_str();
    while (*p) {
        while (*p == ' ' || *p == '\t') {
            ++p;
        }
        if (!*p) {
            break;
        }
        const char* s = p;
        while (*p && *p != ' ' && *p != '\t') {
            ++p;
        }
        out.emplace_back(s, static_cast<size_t>(p - s));
    }
    return out;
}

/* One box-shadow layer: "ox oy blur [spread] color" (the caller strips an
 * optional leading "inset"). */
void paint_one_shadow(whaleui_render_t* r, whaleui_layout_node_t* n,
                      int off_x, int off_y, const Clip* clip,
                      const std::string& v, bool inset)
{
    int ox = 0, oy = 0, blur = 0, spread = 0;
    unsigned int col = 0;
    if (parse_shadow(v, ox, oy, blur, col, &spread) != 0) {
        return;
    }
    unsigned int a = (col >> 24) & 0xFF;
    unsigned int aa = static_cast<unsigned>(a * n->opacity);
    if (aa == 0) {
        return;
    }
    unsigned int colc = (aa << 24) | (col & 0x00FFFFFF);
    int radius = 0;
    std::string br = sget(n->style, "border-radius");
    if (!br.empty()) {
        radius = std::atoi(br.c_str());
    }
    /* off-screen shadows cost nothing (inset: only the box matters) */
    int sx0 = n->border.x + off_x + ox - blur;
    int sy0 = n->border.y + off_y + oy - blur;
    if (!inset &&
        (sx0 + n->border.w + 2 * blur <= 0 || sx0 >= r->fb_w ||
         sy0 + n->border.h + 2 * blur <= 0 || sy0 >= r->fb_h)) {
        return;
    }
    int bx = n->border.x + off_x;
    int by = n->border.y + off_y;
    if (blur <= 0) {
        if (inset) {
            /* hard inner shadow: the box minus the (spread-shrunk, offset)
             * inner rect - the four uncovered strips. GPU: the inset CS
             * samples the crisp mask (blur 0 is legal there). */
            if (g_gpu) {
                whaleui_gpu_inset(g_gpu, static_cast<float>(bx),
                                  static_cast<float>(by),
                                  static_cast<float>(n->border.w),
                                  static_cast<float>(n->border.h),
                                  static_cast<float>(radius), 0.0f,
                                  static_cast<float>(ox),
                                  static_cast<float>(oy),
                                  static_cast<float>(spread), colc);
                return;
            }
            int l = spread + (ox > 0 ? ox : 0);
            int rt = spread + (ox < 0 ? -ox : 0);
            int t = spread + (oy > 0 ? oy : 0);
            int b = spread + (oy < 0 ? -oy : 0);
            if (l > n->border.w) l = n->border.w;
            if (rt > n->border.w) rt = n->border.w;
            if (t > n->border.h) t = n->border.h;
            if (b > n->border.h) b = n->border.h;
            int rad0 = 0;
            std::string br0 = sget(n->style, "border-radius");
            if (!br0.empty()) {
                rad0 = std::atoi(br0.c_str());
            }
            /* the middle strips leave the corner arcs to the side strips
             * (a browser miters them; blur 0 rings are hairlines) */
            if (l > 0) {
                fill_round_rect(r->pixels, r->fb_w, r->fb_h, bx, by, l,
                                n->border.h, rad0, colc, clip);
            }
            if (rt > 0) {
                fill_round_rect(r->pixels, r->fb_w, r->fb_h,
                                bx + n->border.w - rt, by, rt, n->border.h,
                                rad0, colc, clip);
            }
            int midw = n->border.w - l - rt;
            if (midw > 0) {
                if (t > 0) {
                    fill_rect(r->pixels, r->fb_w, r->fb_h, bx + l, by, midw,
                              t, colc, clip);
                }
                if (b > 0) {
                    fill_rect(r->pixels, r->fb_w, r->fb_h, bx + l,
                              by + n->border.h - b, midw, b, colc, clip);
                }
            }
            return;
        }
        /* hard OUTER shadow (blur 0): one fill grown by spread - this is
         * the "0 0 0 3px rgba(...)" focus ring the themes write */
        int hx = bx + ox - spread;
        int hy = by + oy - spread;
        int hw = n->border.w + 2 * spread;
        int hh = n->border.h + 2 * spread;
        if (hw <= 0 || hh <= 0) {
            return;
        }
        int rad0 = 0;
        std::string br0 = sget(n->style, "border-radius");
        if (!br0.empty()) {
            rad0 = std::atoi(br0.c_str());
        }
        if (rad0 > 0) {
            fill_round_rect(r->pixels, r->fb_w, r->fb_h, hx, hy, hw, hh,
                            rad0, colc, clip);
        } else {
            fill_rect(r->pixels, r->fb_w, r->fb_h, hx, hy, hw, hh, colc,
                      clip);
        }
        return;
    }
    /* GPU path: the mipmap blur approximation (blur_tex + multi-level
     * resampling) - one shape + one sampling quad instead of blur/2
     * concentric fills. Inset shadows blend 1 - blurred_mask(px - offset)
     * of the spread-shrunk box over the painted geometry (after the
     * geometry pass). */
    if (g_gpu) {
        if (inset) {
            whaleui_gpu_inset(g_gpu, static_cast<float>(bx),
                              static_cast<float>(by),
                              static_cast<float>(n->border.w),
                              static_cast<float>(n->border.h),
                              static_cast<float>(radius),
                              static_cast<float>(blur),
                              static_cast<float>(ox),
                              static_cast<float>(oy),
                              static_cast<float>(spread), colc);
        } else {
            whaleui_gpu_shadow(g_gpu,
                               static_cast<float>(bx + ox - spread),
                               static_cast<float>(by + oy - spread),
                               static_cast<float>(n->border.w + 2 * spread),
                               static_cast<float>(n->border.h + 2 * spread),
                               static_cast<float>(radius),
                               static_cast<float>(blur), colc);
        }
        return;
    }
    /* concentric layers, alpha fading outwards (inset: inwards); skip the
     * near-invisible outermost ring and step by 2px (half the fill cost,
     * gradient still smooth). Inset layers shift with the offset: the
     * strip on the offset side grows, the opposite side shrinks. */
    for (int k = blur - 1; k >= 1; k -= 2) {
        unsigned int ka = static_cast<unsigned>(a * (blur - k + 1) / (blur + 1));
        if (ka < 4) {
            continue;
        }
        unsigned int c = (ka << 24) | (col & 0x00FFFFFF);
        int sx, sy, sw, sh;
        if (inset) {
            int l = spread + k + (ox > 0 ? ox : 0);
            int t = spread + k + (oy > 0 ? oy : 0);
            int rt = spread + k + (ox < 0 ? -ox : 0);
            int b = spread + k + (oy < 0 ? -oy : 0);
            sx = bx + l;
            sy = by + t;
            sw = n->border.w - l - rt;
            sh = n->border.h - t - b;
            if (sw <= 0 || sh <= 0) {
                continue;
            }
        } else {
            sx = bx + ox - spread - k;
            sy = by + oy - spread - k;
            sw = n->border.w + 2 * spread + 2 * k;
            sh = n->border.h + 2 * spread + 2 * k;
        }
        if (radius > 0) {
            fill_round_rect(r->pixels, r->fb_w, r->fb_h, sx, sy, sw, sh,
                            radius, c, clip);
        } else {
            fill_rect(r->pixels, r->fb_w, r->fb_h, sx, sy, sw, sh, c, clip);
        }
    }
}

/* box-shadow: a comma-separated layer list. Per CSS the FIRST layer is on
 * top, so they are painted back to front. Previously only the first layer
 * was read - which for the themes' "ambient + key" pairs dropped the key
 * shadow, the visible one. */
void paint_shadow(whaleui_render_t* r, whaleui_layout_node_t* n,
                  int off_x, int off_y, const Clip* clip)
{
    std::string v = sget(n->style, "box-shadow");
    if (v.empty() || v == "none") {
        return;
    }
    /* split on top-level commas (rgba(0,0,0,.2) keeps its own) */
    std::vector<std::string> layers;
    size_t depth = 0, start = 0;
    for (size_t i = 0; i < v.size(); ++i) {
        char ch = v[i];
        if (ch == '(') {
            ++depth;
        } else if (ch == ')') {
            if (depth) {
                --depth;
            }
        } else if (ch == ',' && depth == 0) {
            layers.push_back(v.substr(start, i - start));
            start = i + 1;
        }
    }
    layers.push_back(v.substr(start));
    for (size_t li = layers.size(); li-- > 0;) {
        std::string layer = layers[li];
        size_t b = layer.find_first_not_of(" \t");
        if (b == std::string::npos) {
            continue;
        }
        size_t e = layer.find_last_not_of(" \t");
        layer = layer.substr(b, e - b + 1);
        if (layer.empty()) {
            continue;
        }
        /* "inset" prefix: the shadow projects inward from the box edges */
        bool inset = false;
        if (layer.compare(0, 5, "inset") == 0 &&
            (layer.size() == 5 || layer[5] == ' ' || layer[5] == '\t')) {
            inset = true;
            layer = layer.substr(5);
        }
        paint_one_shadow(r, n, off_x, off_y, clip, layer, inset);
    }
}

/* outline: [width] [style] [color] plus outline-offset. Drawn just OUTSIDE
 * the border box (it never affects layout, which is why every theme reaches
 * for it on :focus). Width defaults to 3px (CSS "medium") when the
 * shorthand carries only a color/style; the color defaults to the text
 * color (currentColor). dotted/dashed are approximated with dashes - a
 * focus ring only needs to be visible, and the aero/metro themes write
 * "dotted". */
void paint_outline(whaleui_render_t* r, whaleui_layout_node_t* n,
                   int off_x, int off_y, int bw, int bh, const Clip* clip)
{
    std::string v = sget(n->style, "outline");
    if (v == "none") {
        return;
    }
    std::string lw = sget(n->style, "outline-width");
    std::string ls = sget(n->style, "outline-style");
    std::string lc = sget(n->style, "outline-color");
    if (v.empty() && lw.empty() && ls.empty() && lc.empty()) {
        return;
    }
    int width = 0;
    bool width_set = false;
    std::string style_k = ls;
    std::string color_k = lc;
    if (!v.empty() && v != "none") {
        const char* p = v.c_str();
        while (*p) {
            while (*p == ' ' || *p == '\t') {
                ++p;
            }
            if (!*p) {
                break;
            }
            const char* b = p;
            while (*p && *p != ' ' && *p != '\t') {
                ++p;
            }
            std::string t(b, static_cast<size_t>(p - b));
            if (t[0] == '-' || (t[0] >= '0' && t[0] <= '9')) {
                width = std::atoi(t.c_str());
                width_set = true;
            } else if (t == "solid" || t == "dashed" || t == "dotted" ||
                       t == "double" || t == "groove" || t == "ridge" ||
                       t == "inset" || t == "outset" || t == "none" ||
                       t == "auto") {
                style_k = t;
            } else {
                color_k = t;
            }
        }
    }
    if (style_k == "none") {
        return;
    }
    if (!width_set) {
        width = lw.empty() ? 3 : std::atoi(lw.c_str());
    }
    if (width <= 0) {
        return;
    }
    unsigned int col = 0;
    if (!color_k.empty()) {
        whaleui_render_parse_color(color_k.c_str(), &col);
    }
    if (col == 0) {
        col = color_of(n->style, "color", 0xFF000000);
    }
    unsigned int a = (col >> 24) & 0xFF;
    if (a == 0) {
        return;
    }
    unsigned int a8 = static_cast<unsigned>(a * n->opacity);
    unsigned int c = (a8 << 24) | (col & 0x00FFFFFF);
    int off = 0;
    std::string osv = sget(n->style, "outline-offset");
    if (!osv.empty()) {
        off = std::atoi(osv.c_str());
    }
    int x = n->border.x + off_x - off - width;
    int y = n->border.y + off_y - off - width;
    int w = bw + 2 * (off + width);
    int h = bh + 2 * (off + width);
    if (w <= 0 || h <= 0) {
        return;
    }
    bool dashed = style_k == "dotted" || style_k == "dashed";
    int seg = style_k == "dotted" ? 2 : 4;
    const int skip = 2;
    if (!dashed) {
        fill_rect(r->pixels, r->fb_w, r->fb_h, x, y, w, width, c, clip);
        fill_rect(r->pixels, r->fb_w, r->fb_h, x, y + h - width, w, width,
                  c, clip);
        fill_rect(r->pixels, r->fb_w, r->fb_h, x, y, width, h, c, clip);
        fill_rect(r->pixels, r->fb_w, r->fb_h, x + w - width, y, width, h,
                  c, clip);
        return;
    }
    for (int i = 0; i < w; i += seg + skip) {
        int s = seg;
        if (i + s > w) {
            s = w - i;
        }
        fill_rect(r->pixels, r->fb_w, r->fb_h, x + i, y, s, width, c, clip);
        fill_rect(r->pixels, r->fb_w, r->fb_h, x + i, y + h - width, s,
                  width, c, clip);
    }
    for (int i = 0; i < h; i += seg + skip) {
        int s = seg;
        if (i + s > h) {
            s = h - i;
        }
        fill_rect(r->pixels, r->fb_w, r->fb_h, x, y + i, width, s, c, clip);
        fill_rect(r->pixels, r->fb_w, r->fb_h, x + w - width, y + i, width,
                  s, c, clip);
    }
}

SDL_Surface* img_surface(whaleui_render_t* r, const std::string& src)
{
    if (src.empty()) {
        return nullptr;
    }
    auto it = r->images.find(src);
    if (it != r->images.end()) {
        return it->second;
    }
    SDL_Surface* s = nullptr;
    if (src.compare(0, 7, "http://") != 0 &&
        src.compare(0, 8, "https://") != 0 &&
        src.compare(0, 5, "data:") != 0) {
        std::string path = src;
        if (path.compare(0, 7, "file://") == 0) {
            path = path.substr(7);
            if (!path.empty() && (path[0] == '/' || path[0] == '\\')) {
                path = path.substr(1); /* file:///C:/x -> C:/x */
            }
        }
#ifdef WHALEUI_BUILD_FULL
        s = IMG_Load(path.c_str());
#else
        /* stb_image decode (lite/minimal have no SDL_image) */
        int iw = 0, ih = 0, ich = 0;
        unsigned char* px = stbi_load(path.c_str(), &iw, &ih, &ich, 4);
        if (px && iw > 0 && ih > 0) {
            s = SDL_CreateSurface(iw, ih, SDL_PIXELFORMAT_RGBA32);
            if (s) {
                std::memcpy(s->pixels, px, static_cast<size_t>(iw) * ih * 4);
            }
        }
        if (px) {
            stbi_image_free(px);
        }
#endif
    }
    r->images[src] = s;
    return s;
}

void paint_img(whaleui_render_t* r, whaleui_layout_node_t* n, int off_x,
               int off_y, const Clip* clip)
{
    size_t alen = 0;
    const lxb_char_t* src = lxb_dom_element_get_attribute(
        n->el, (const lxb_char_t*)"src", 3, &alen);
    std::string srcs = src ? std::string(reinterpret_cast<const char*>(src),
                                         alen)
                           : std::string();
    int x = n->border.x + off_x;
    int y = n->border.y + off_y;
    int w = n->border.w;
    int h = n->border.h;
    if (x + w <= 0 || y + h <= 0 || x >= r->fb_w || y >= r->fb_h) {
        return;
    }
    SDL_Surface* img = img_surface(r, srcs);
    if (img && img->w > 0 && img->h > 0) {
        /* object-fit: cover keeps the aspect and crops, contain letterboxes,
         * fill (default) stretches. object-position (default center) moves
         * the fitted image inside the box: keywords / % / px per axis. */
        std::string of = sget(n->style, "object-fit");
        int dw = w, dh = h, dx = x, dy = y;
        if (of == "cover" || of == "contain") {
            float ar = static_cast<float>(img->w) / img->h;
            float dar = w > 0 ? static_cast<float>(w) / h : 1.0f;
            /* cover takes the larger scale (crop the overflow), contain
             * the smaller (letterbox the remainder): fit by width iff the
             * width is the constraining axis. (The old
             * `(cover)==(ar>dar)` test had it backwards: square-in-wide
             * under contain overflowed the box height, and every cover
             * left a gap on the wrong axis.) */
            bool by_w = (of == "cover") != (ar > dar);
            if (by_w) {
                dh = static_cast<int>(w / ar);
            } else {
                dw = static_cast<int>(h * ar);
            }
            float fx = 0.5f, fy = 0.5f; /* object-position, 0..1 */
            std::vector<std::string> op =
                split_space2(sget(n->style, "object-position"));
            if (op.size() == 1) {
                /* single value: horizontal unless top/bottom */
                if (op[0] == "left") {
                    fx = 0.0f;
                } else if (op[0] == "right") {
                    fx = 1.0f;
                } else if (op[0] == "top") {
                    fy = 0.0f;
                } else if (op[0] == "bottom") {
                    fy = 1.0f;
                } else if (op[0] == "center") {
                    /* defaults */
                } else if (!op[0].empty() && op[0].back() == '%') {
                    fx = static_cast<float>(std::atof(op[0].c_str())) / 100.0f;
                } else if (!op[0].empty()) {
                    float pxv = static_cast<float>(std::atof(op[0].c_str()));
                    fx = (w - dw) != 0 ? pxv / (w - dw) : 0.5f;
                }
            } else if (op.size() >= 2) {
                fx = op[0] == "left"    ? 0.0f
                     : op[0] == "right" ? 1.0f
                     : op[0] == "center"
                         ? 0.5f
                         : (!op[0].empty() && op[0].back() == '%'
                                ? static_cast<float>(std::atof(op[0].c_str())) /
                                      100.0f
                                : ((w - dw) != 0
                                       ? static_cast<float>(
                                             std::atof(op[0].c_str())) /
                                             (w - dw)
                                       : 0.5f));
                fy = op[1] == "top"    ? 0.0f
                     : op[1] == "bottom" ? 1.0f
                     : op[1] == "center"
                         ? 0.5f
                         : (!op[1].empty() && op[1].back() == '%'
                                ? static_cast<float>(std::atof(op[1].c_str())) /
                                      100.0f
                                : ((h - dh) != 0
                                       ? static_cast<float>(
                                             std::atof(op[1].c_str())) /
                                             (h - dh)
                                       : 0.5f));
            }
            if (fx < 0.0f) {
                fx = 0.0f;
            }
            if (fx > 1.0f) {
                fx = 1.0f;
            }
            if (fy < 0.0f) {
                fy = 0.0f;
            }
            if (fy > 1.0f) {
                fy = 1.0f;
            }
            dx = x + static_cast<int>((w - dw) * fx);
            dy = y + static_cast<int>((h - dh) * fy);
        }
        if (dw > 0 && dh > 0) {
            SDL_Surface* scaled = SDL_ScaleSurface(img, dw, dh,
                                                   SDL_SCALEMODE_LINEAR);
            /* blend_surface reads RGBA32 (s[3] is alpha): an RGB24 source
             * (JPEG, small PNG) has no alpha byte, so the pixel AFTER each
             * triplet was read as alpha - blue pixels (R=0) came out
             * transparent and vanished. Convert once. */
            SDL_Surface* rgba = scaled;
            if (scaled &&
                scaled->format != SDL_PIXELFORMAT_RGBA32) {
                rgba = SDL_ConvertSurface(scaled, SDL_PIXELFORMAT_RGBA32);
                SDL_DestroySurface(scaled);
            }
            if (rgba) {
                if (g_gpu) {
                    blend_surface(r->text_layer, r->fb_w, r->fb_h, rgba,
                                  dx, dy, clip, nullptr);
                } else {
                    blend_surface(r->pixels, r->fb_w, r->fb_h, rgba,
                                  dx, dy, clip, nullptr);
                }
                SDL_DestroySurface(rgba);
            }
        }
        return;
    }
    /* placeholder box: dim fill + hairline border, so broken images still
     * occupy their laid-out space visibly */
    unsigned int dim = 0xFF2A2E38;
    fill_rect(r->pixels, r->fb_w, r->fb_h, x, y, w, h, dim, clip);
    unsigned int edge = 0xFF3A4150;
    fill_rect(r->pixels, r->fb_w, r->fb_h, x, y, w, 1, edge, clip);
    fill_rect(r->pixels, r->fb_w, r->fb_h, x, y + h - 1, w, 1, edge, clip);
    fill_rect(r->pixels, r->fb_w, r->fb_h, x, y, 1, h, edge, clip);
    fill_rect(r->pixels, r->fb_w, r->fb_h, x + w - 1, y, 1, h, edge, clip);
}

void paint_canvas(whaleui_render_t* r, whaleui_layout_node_t* n, int off_x,
                  int off_y, const Clip* clip)
{
    if (!r || !n || !n->el) return;
    whaleui_canvas_context_t* c = whaleui_canvas_context_for(n->el);
    if (!c || c->w <= 0 || c->h <= 0) return;
    int x = n->border.x + off_x;
    int y = n->border.y + off_y;
    int w = n->border.w;
    int h = n->border.h;
    if (w <= 0 || h <= 0) return;
    std::vector<unsigned int>& fb = g_gpu ? r->text_layer : r->pixels;
    for (int j = 0; j < h; ++j) {
        int ty = y + j;
        if (ty < 0 || ty >= r->fb_h) continue;
        if (clip && (ty < clip->y || ty >= clip->y + clip->h)) continue;
        int sy = j * c->h / h;
        for (int i = 0; i < w; ++i) {
            int tx = x + i;
            if (tx < 0 || tx >= r->fb_w) continue;
            if (clip && (tx < clip->x || tx >= clip->x + clip->w)) continue;
            int sx = i * c->w / w;
            unsigned int s = c->px[(size_t)sy * c->w + sx];
            unsigned int a = (s >> 24) & 255;
            if (!a) continue;
            unsigned int d = fb[(size_t)ty * r->fb_w + tx];
            if (a == 255) { fb[(size_t)ty * r->fb_w + tx] = s; continue; }
            unsigned int sr = (s >> 16) & 255, sg = (s >> 8) & 255, sb = s & 255;
            unsigned int dr = (d >> 16) & 255, dg = (d >> 8) & 255, db = d & 255;
            unsigned int nr = (sr * a + dr * (255 - a)) / 255;
            unsigned int ng = (sg * a + dg * (255 - a)) / 255;
            unsigned int nb = (sb * a + db * (255 - a)) / 255;
            fb[(size_t)ty * r->fb_w + tx] = 0xFF000000u | (nr << 16) | (ng << 8) | nb;
        }
    }
}

/* Mark a node's subtree bounds stale and BUBBLE the mark to the root. Only the
 * path to the root is touched, so a local relayout no longer invalidates every
 * node's bounds in a 30k-node tree. */
void mark_bounds_dirty(whaleui_layout_node_t* n)
{
    for (; n && !n->bd; n = n->parent) {
        n->bd = 1;
    }
}

/* when the WHOLE tree moved (full relayout, scroll, new rows) every node's
 * bounds are stale - distinct from mark_bounds_dirty(), which is for a local
 * relayout and only walks up to the root */
void mark_bounds_dirty_all(whaleui_layout_node_t* n)
{
    if (!n) {
        return;
    }
    n->bd = 1;
    for (whaleui_layout_node_t* c = n->first_child; c; c = c->next) {
        mark_bounds_dirty_all(c);
    }
}

void compute_paint_bounds(whaleui_layout_node_t* n)
{
    if (!n->bd) {
        return; /* still valid: nothing under here moved */
    }
    whaleui_rect_t b = n->border;
    for (whaleui_layout_node_t* c = n->first_child; c; c = c->next) {
        if (!c->visible) {
            continue;
        }
        compute_paint_bounds(c);
        int x0 = b.x, y0 = b.y, x1 = b.x + b.w, y1 = b.y + b.h;
        int cx0 = c->bounds.x, cy0 = c->bounds.y;
        int cx1 = c->bounds.x + c->bounds.w, cy1 = c->bounds.y + c->bounds.h;
        if (cx0 < x0) x0 = cx0;
        if (cy0 < y0) y0 = cy0;
        if (cx1 > x1) x1 = cx1;
        if (cy1 > y1) y1 = cy1;
        b.x = x0;
        b.y = y0;
        b.w = x1 - x0;
        b.h = y1 - y0;
    }
    n->bounds = b;
    /* per-chunk merged boxes: same members, so refresh them in the same pass.
     * A paint / hit walk can then skip a whole chunk (WUI_CHUNK siblings) with
     * one box test instead of testing every sibling. */
    for (whaleui_child_chunk* ck = n->chunks; ck; ck = ck->next) {
        whaleui_rect_t cb;
        bool have = false;
        for (whaleui_layout_node_t* c = ck->first;
             c && c->chunk == ck; c = c->next) {
            if (!c->visible) {
                continue;
            }
            if (!have) {
                cb = c->bounds;
                have = true;
                continue;
            }
            int x0 = cb.x, y0 = cb.y;
            int x1 = cb.x + cb.w, y1 = cb.y + cb.h;
            int cx0 = c->bounds.x, cy0 = c->bounds.y;
            int cx1 = c->bounds.x + c->bounds.w;
            int cy1 = c->bounds.y + c->bounds.h;
            if (cx0 < x0) x0 = cx0;
            if (cy0 < y0) y0 = cy0;
            if (cx1 > x1) x1 = cx1;
            if (cy1 > y1) y1 = cy1;
            cb.x = x0;
            cb.y = y0;
            cb.w = x1 - x0;
            cb.h = y1 - y0;
        }
        ck->box = have ? cb : whaleui_rect_t{0, 0, 0, 0};
    }
    n->bd = 0;
}

const int kCullMargin = 64;

/* z-order: elements that paint on top of normal flow ("high roots").
 * Unified bottom-layer rule, NOT per-element special-casing: anything
 * with z-index > 0 or a fixed/sticky position gets its own paint layer
 * (UA default CSS raises popup/fixed elements). */
bool is_high_root(const whaleui_layout_node_t* n)
{
    if (!n->el || n->is_text) {
        return false;
    }
    return n->hz || n->fx || n->sk;
}

/* should a high root clear the old text under it? Only when its own
 * background is (near-)opaque: then it occludes the lower layers and the
 * text_layer's "text always on top" composite must not let the lower
 * glyphs show through. Semi-transparent high roots (a blur header, a
 * noise overlay) leave the lower text in place - it shows through their
 * background, which is the correct CSS stacking. */
static bool high_root_occludes(const whaleui_layout_node_t* n)
{
    if (!is_high_root(n)) {
        return false;
    }
    unsigned int bg = color_of(n->style, "background-color", 0);
    if (bg == 0) {
        bg = color_of(n->style, "background", 0);
    }
    return ((bg >> 24) & 0xFF) >= 250;
}

/* clear a rectangle of the text layer (the old glyphs underneath a
 * higher layer's area must not survive the composite) */
void text_layer_clear(whaleui_render_t* r, int x, int y, int w, int h)
{
    if (x < 0) {
        w += x;
        x = 0;
    }
    if (y < 0) {
        h += y;
        y = 0;
    }
    if (x + w > r->fb_w) {
        w = r->fb_w - x;
    }
    if (y + h > r->fb_h) {
        h = r->fb_h - y;
    }
    if (w <= 0 || h <= 0) {
        return;
    }
    for (int yy = y; yy < y + h; ++yy) {
        std::fill(r->text_layer.begin() + static_cast<size_t>(yy) * r->fb_w + x,
                  r->text_layer.begin() + static_cast<size_t>(yy) * r->fb_w + x + w,
                  0);
    }
}

void clear_subtree_text(whaleui_render_t* r,
                        whaleui_layout_node_t* nd, int off_x,
                        int off_y)
{
    if (!nd->visible) {
        return;
    }
    int nox = off_x, noy = off_y;
    if (nd->el && !nd->is_text && nd->fx) {
        nox = 0;
        noy = 0;
    }
    text_layer_clear(r, nd->border.x + nox, nd->border.y + noy,
                     nd->border.w, nd->border.h);
    int coy = noy + (nd->is_text ? 0 : scroll_delta(r, nd));
    for (whaleui_layout_node_t* c = nd->first_child; c; c = c->next) {
        clear_subtree_text(r, c, nox, coy);
    }
}

bool paint_cull(whaleui_render_t* r, whaleui_layout_node_t* n, int off_x,
                int off_y, const Clip* clip)
{
    (void)r;
    if (!clip || clip->w <= 0 || clip->h <= 0) {
        return false;
    }
    int x0 = n->bounds.x + off_x - kCullMargin;
    int y0 = n->bounds.y + off_y - kCullMargin;
    int x1 = n->bounds.x + n->bounds.w + off_x + kCullMargin;
    int y1 = n->bounds.y + n->bounds.h + off_y + kCullMargin;
    return x1 <= clip->x || x0 >= clip->x + clip->w ||
           y1 <= clip->y || y0 >= clip->y + clip->h;
}

/* Same rule as paint_cull, applied to a whole chunk's merged box: one test
 * decides for up to WUI_CHUNK siblings. */
bool chunk_culled(const whaleui_child_chunk* ck, int off_x, int off_y,
                  const Clip* clip)
{
    if (!ck || !clip || clip->w <= 0 || clip->h <= 0) {
        return false;
    }
    int x0 = ck->box.x + off_x - kCullMargin;
    int y0 = ck->box.y + off_y - kCullMargin;
    int x1 = ck->box.x + ck->box.w + off_x + kCullMargin;
    int y1 = ck->box.y + ck->box.h + off_y + kCullMargin;
    return x1 <= clip->x || x0 >= clip->x + clip->w ||
           y1 <= clip->y || y0 >= clip->y + clip->h;
}

void paint_node(whaleui_render_t* r, whaleui_layout_node_t* n, int off_x,
                int off_y, int& seq, int sel_lo, int sel_hi,
                const Clip* clip, bool tc)
{
    if (!n->visible) {
        return;
    }
    const int my_seq = seq++;
    /* transform value read ONCE per node (the tc check below and the paint
     * transform block both need it); position:fixed is checked only when no
     * transform is present. Transformed / fixed subtrees are painted at
     * offset positions the layout bounds don't know about: never cull them,
     * and propagate the flag down so descendants use the same rule. */
    std::string ntv; /* "transform" value of this node ("" = none) */
    bool has_xf = false;
    if (n->el && !n->is_text) {
        has_xf = n->xf != 0;
        if (!tc && has_xf) {
            ntv = sget(n->style, "transform");
            tc = true;
        } else if (!tc && n->fx) {
            tc = true;
        } else if (!tc && n->sk) {
            /* sticky pins the box at top:N while scrolling, so its painted
             * box leaves the layout bounds - culling on the laid-out
             * position would drop it (and its subtree) mid-scroll */
            tc = true;
        }
    }
    /* a selection endpoint outside the repaint region must still receive
     * its sequence number (sel_seq does the same), so the in-viewport
     * middle of the selection keeps highlighting. Text runs skip the
     * subtree cull entirely: their laid-out bounds carry the estimated
     * text width, which can fall short of the real glyph extent (inline
     * lines, letter-spacing) - culling on it drops glyphs that actually
     * reach the repaint strip. paint_text has its own framebuffer check
     * and the clip clips the horizontal overflow. */
    if (!tc && !n->is_text &&
        !(n->el && (n->el == r->sel_anchor_el ||
                    n->el == r->sel_focus_el)) &&
        paint_cull(r, n, off_x, off_y, clip)) {
        return; /* whole subtree outside the repaint region */
    }
    if (n->is_text) {
        paint_text(r, n, off_x, off_y, my_seq, sel_lo, sel_hi, clip);
        return;
    }
    /* position:fixed elements are laid out against the viewport and must
     * not move with ancestor scroll offsets */
    if (n->fx) {
        off_x = 0;
        off_y = 0;
    }
    /* position:sticky: keep the box pinned inside the top/left/right/
     * bottom offsets once scrolling would push it past an edge (the layout
     * pass already shifted the box by the scroll amount, so border + off
     * is the current viewport position). top/left pin against the viewport
     * origin; bottom/right pin against the viewport far edge (r->fb_w/h);
     * the box also never leaves its parent's content box (container
     * clamping, in document coords). Simplified to the page/root scroll. */
    if (n->sk) {
        int cur_x = n->border.x + off_x;
        int cur_y = n->border.y + off_y;
        std::string stv = sget(n->style, "top");
        std::string slv = sget(n->style, "left");
        std::string sbv = sget(n->style, "bottom");
        std::string srv = sget(n->style, "right");
        if (!stv.empty() && stv != "auto") {
            int st = std::atoi(stv.c_str());
            if (cur_y < st) {
                off_y += st - cur_y;
                cur_y = st;
            }
        }
        if (!slv.empty() && slv != "auto") {
            int sl = std::atoi(slv.c_str());
            if (cur_x < sl) {
                off_x += sl - cur_x;
                cur_x = sl;
            }
        }
        if (!sbv.empty() && sbv != "auto") {
            int sb = std::atoi(sbv.c_str());
            int lim = r->fb_h - n->border.h - sb;
            if (cur_y > lim) {
                off_y -= cur_y - lim;
                cur_y = lim;
            }
        }
        if (!srv.empty() && srv != "auto") {
            int sr = std::atoi(srv.c_str());
            int lim = r->fb_w - n->border.w - sr;
            if (cur_x > lim) {
                off_x -= cur_x - lim;
                cur_x = lim;
            }
        }
        if (n->parent && !n->parent->is_text) {
            /* container clamp (document coords): the sticky box never
             * leaves its parent's content box */
            int pex = n->parent->border.x + n->parent->border.w;
            int pey = n->parent->border.y + n->parent->border.h;
            if (n->border.y + n->border.h > pey) {
                int over = n->border.y + n->border.h - pey;
                off_y -= over;
            }
            if (n->border.x + n->border.w > pex) {
                off_x -= n->border.x + n->border.w - pex;
            }
        }
    }
    /* transform: translate (px/%) + scale around the transform-origin +
     * clockwise rotate around the transform-origin (approximate: the box's
     * own background/border rotate with the rasterizer, text and children
     * stay upright). The shifted box is drawn here and off_x/off_y carry
     * the translation into the subtree. Child coordinates are NOT scaled.
     * ponytail: true 2D transform stacks are a later step. */
    float tdx = 0.0f, tdy = 0.0f, tsx = 1.0f, tsy = 1.0f;
    float trot = 0.0f;
    float tskx = 0.0f, tsky = 0.0f;
    float toox = 0.0f, toooy = 0.0f; /* transform-origin anchor, px in-box */
    if (has_xf) {
        whaleui_transform_t tf;
        if (whaleui_transform_eval(ntv.c_str(),
                                   static_cast<float>(n->border.w),
                                   static_cast<float>(n->border.h), &tf) == 0) {
            tdx = tf.tx;
            tdy = tf.ty;
            tsx = tf.sx;
            tsy = tf.sy;
            trot = tf.rot;
            tskx = tf.skx;
            tsky = tf.sky;
        }
        whaleui_transform_origin_eval(sget(n->style, "transform-origin").c_str(),
                                      static_cast<float>(n->border.w),
                                      static_cast<float>(n->border.h),
                                      &toox, &toooy);
    }
    bool has_rot = trot != 0.0f || tskx != 0.0f || tsky != 0.0f;
    int bw = n->border.w;
    int bh = n->border.h;
    if (tsx != 1.0f || tsy != 1.0f) {
        /* scale keeps the transform-origin fixed: the box grows/shrinks
         * away from the anchor (default center = the old behavior) */
        bw = static_cast<int>(n->border.w * tsx);
        bh = static_cast<int>(n->border.h * tsy);
    }
    int nox = off_x + static_cast<int>(tdx) +
              static_cast<int>(toox * (1.0f - tsx));
    int noy = off_y + static_cast<int>(tdy) +
              static_cast<int>(toooy * (1.0f - tsy));
    /* clip-path: parse against this box and push (stacked; children
     * inherit). The shape is stored in-box; emitters map it onto each
     * quad. polygon() parses but reports unsupported (plain paint).
     * Placed after transform/scale resolve (bw/bh/nox/noy final). */
    bool pushed_clip = false;
    if (n->el) {
        std::string cpv = sget(n->style, "clip-path");
        if (!cpv.empty() && cpv != "none") {
            ClipPath cps;
            if (parse_clip_path(cpv.c_str(), static_cast<float>(bw),
                                static_cast<float>(bh),
                                &cps) == 0 &&
                cps.type > 0) {
                ClipPathActive act;
                act.shape = cps;
                act.bx = n->border.x + nox;
                act.by = n->border.y + noy;
                act.bw = bw;
                act.bh = bh;
                g_clip_stack.push_back(act);
                pushed_clip = true;
            }
        }
    }
    /* mask-image: linear-gradient alpha mask over this box (stacked like
     * clip-path; children inherit). Only the alpha channel matters: the
     * gradient's corners project to per-corner mask values (same axis math
     * as fill_gradient). Non-linear masks parse but are skipped (opaque).
     * -webkit-mask-image is accepted as an alias. */
    bool pushed_mask = false;
    if (n->el) {
        std::string mkv = sget(n->style, "mask-image");
        if (mkv.empty()) {
            mkv = sget(n->style, "-webkit-mask-image");
        }
        if (!mkv.empty() && mkv != "none") {
            Gradient mg;
            if (parse_gradient(mkv, mg) && mg.type == 0 &&
                !mg.stops.empty()) {
                MaskActive mk;
                mk.active = true;
                mk.bx = n->border.x + nox;
                mk.by = n->border.y + noy;
                mk.bw = bw;
                mk.bh = bh;
                mask_from_linear(mg, bw, bh, mk.m);
                g_mask_stack.push_back(mk);
                pushed_mask = true;
            }
        }
    }
    /* z-order high root with an opaque background: this element's layer
     * occludes lower layers - clear the old text under it so lower
     * glyphs do not show through its background. Unified rule; the popup
     * and fixed headers are just z-raised elements. */
    if (high_root_occludes(n)) {
        clear_subtree_text(r, n, off_x, off_y);
    }
    /* overflow: hidden/auto/scroll clips descendants to the border box
     * (auto/scroll containers also shift children by scroll_y at layout).
     * overflow-x/-y longhands count when the shorthand is absent.
     * contain: paint (or strict/content, which include paint) clips the
     * same way - the cheapest correct subset of CSS containment
     * (layout/size/style containment are no-ops, documented). */
    Clip self;
    const Clip* eff = clip;
    std::string ov = sget(n->style, "overflow");
    if (ov.empty()) {
        std::string ox = sget(n->style, "overflow-x");
        std::string oy = sget(n->style, "overflow-y");
        if (ox == "hidden" || ox == "auto" || ox == "scroll" ||
            oy == "hidden" || oy == "auto" || oy == "scroll") {
            ov = "hidden"; /* clip; scroll deltas still come from layout */
        }
    }
    /* contain: paint/strict/content clips even when overflow is an
     * explicit "visible" (the check above only fills an EMPTY ov) */
    if (ov.empty() || ov == "visible") {
        std::string cn = sget(n->style, "contain");
        if (cn.find("paint") != std::string::npos ||
            cn.find("strict") != std::string::npos ||
            cn.find("content") != std::string::npos) {
            ov = "hidden"; /* paint containment ~= overflow clip */
        }
    }
    if (ov == "hidden" || ov == "auto" || ov == "scroll") {
        self.x = n->border.x + nox;
        self.y = n->border.y + noy;
        self.w = bw;
        self.h = bh;
        eff = &self;
        /* cull clipped containers fully outside the framebuffer: on a
         * scrolled page most of the document is off-screen, so skip their
         * whole subtree (the biggest scroll-paint win) */
        if (self.y + self.h <= 0 || self.y >= r->fb_h) {
            if (pushed_mask && !g_mask_stack.empty()) {
                g_mask_stack.pop_back();
            }
            if (pushed_clip && !g_clip_stack.empty()) {
                g_clip_stack.pop_back();
            }
            return;
        }
    }
    /* soft shadow first, so the element body covers the inner layers */
#ifndef WHALEUI_BUILD_MINIMAL
    paint_shadow(r, n, nox, noy, eff);
#endif
    /* filter: blur + color-matrix over the element's OWN painted content
     * (body + children + text). The record only carries the box + matrix;
     * the compute pass (after the text composite) does the work. On the
     * CPU path the color matrix applies to the painted pixels right here
     * (after children paint below); blur is GPU-only (like backdrop). */
    float filter_m[4][5];
    float filter_blur = 0;
    std::string filts = sget(n->style, "filter");
    bool has_filter = false;
#ifndef WHALEUI_BUILD_MINIMAL
    if (!filts.empty() && filts != "none" &&
        parse_filter(filts.c_str(), filter_m, &filter_blur) == 0) {
        has_filter = true;
        if (g_gpu) {
            int frad = 0;
            std::string fbr = sget(n->style, "border-radius");
            if (!fbr.empty()) {
                frad = std::atoi(fbr.c_str());
            }
            /* the blur halo spills outside the box: grow the record by
             * the blur radius (the shader clips to the grown rounded box) */
            float fb = filter_blur > 0 ? filter_blur : 0.0f;
            whaleui_gpu_filter(g_gpu,
                               static_cast<float>(n->border.x + nox) - fb,
                               static_cast<float>(n->border.y + noy) - fb,
                               static_cast<float>(bw) + 2.0f * fb,
                               static_cast<float>(bh) + 2.0f * fb,
                               static_cast<float>(frad) + fb, filter_blur,
                               filter_m);
        }
    }
#endif
    /* <img>: bitmap (object-fit) or placeholder replaces the background */
    if (n->el && n->tag_id == WUI_TAG_IMG) {
        paint_img(r, n, nox, noy, eff);
    }
    /* <canvas>: CPU backing store blit (stretched to the layout box) */
    if (n->el && n->tag_id == WUI_TAG_CANVAS) {
        paint_canvas(r, n, nox, noy, eff);
    }
    /* native controls (checkbox/radio/progress) own their box appearance
     * (painted at a fixed native size by paint_checkbox/progress below),
     * so the layout box's background/border must NOT also paint - that
     * drew a second larger frame around the control. Single dispatch
     * point: kind() classifies the node once, the arms below only paint
     * (no second tag test per arm). */
    enum CtrlKind { kCtrlNone, kCtrlCheckRadio, kCtrlProgress, kCtrlEditable,
                    kCtrlSelect };
    CtrlKind kind = kCtrlNone;
    if (!n->pseudo && n->el) {
        if (n->tag_id == WUI_TAG_INPUT && is_check_radio(n->el)) {
            kind = kCtrlCheckRadio;
        } else if (n->tag_id == WUI_TAG_PROGRESS ||
                   n->tag_id == WUI_TAG_METER) {
            kind = kCtrlProgress;
        } else if (is_editable_node(n)) {
            kind = kCtrlEditable;
        } else if (n->tag_id == WUI_TAG_SELECT) {
            kind = kCtrlSelect;
        }
    }
    bool native_ctrl = kind == kCtrlCheckRadio || kind == kCtrlProgress;
    /* mix-blend state lives outside the native_ctrl block (the CPU blend
     * at the tail of paint_node needs it) */
    int mb_mode = -1;
    unsigned int mb_src = 0;
    bool mb_skip_body = false;
    if (!native_ctrl) {
    /* background (border-radius supported). A gradient in `background`/
     * `background-image` paints over the plain color (which shows through
     * the gradient's transparent stops). */
    unsigned int bg = color_of(n->style, "background", 0);
    unsigned int bg2 = color_of(n->style, "background-color", 0);
    if (bg == 0) {
        bg = bg2;
    }
    int radius = 0;
    std::string br = sget(n->style, "border-radius");
    if (!br.empty()) {
        radius = std::atoi(br.c_str());
    }
    unsigned int bg_c = 0; /* inner re-fill color for rounded border rings */
    if (bg != 0) {
        unsigned int a = (bg >> 24) & 0xFF;
        unsigned int a8 = static_cast<unsigned>(a * n->opacity);
        unsigned int c = (a8 << 24) | (bg & 0x00FFFFFF);
        bg_c = c;
    }
    /* backdrop-filter: blur the already-painted background under this box.
     * The element's OWN body (solid background, gradient, border) paints
     * normally afterwards - but routed to the LATE draw list
     * (whaleui_gpu_late_begin), so the backdrop compute pass (which
     * REPLACES the region with the blurred geometry) cannot clobber it:
     * the body ends up on top of the blur, with its gradients and border
     * intact. On scroll frames (pass C skipped) and on the CPU path the
     * body paints in the main pass instead - identical code, different
     * queue. */
    std::string bdf = sget(n->style, "backdrop-filter");
#ifdef WHALEUI_BUILD_MINIMAL
    bool backdrop = false; /* minimal: backdrop blur removed */
#else
    bool backdrop = !bdf.empty() && bdf != "none";
#endif
    bool bdf_gpu = false;
    if (backdrop && g_gpu && g_backdrop_active) {
        float bblur = 8.0f;
        size_t bp = bdf.find("blur(");
        if (bp != std::string::npos) {
            bblur = static_cast<float>(std::atof(bdf.c_str() + bp + 5));
        }
        whaleui_gpu_backdrop(g_gpu, static_cast<float>(n->border.x + nox),
                             static_cast<float>(n->border.y + noy),
                             static_cast<float>(bw), static_cast<float>(bh),
                             static_cast<float>(radius), bblur, 0);
        whaleui_gpu_late_begin(g_gpu);
        bdf_gpu = true;
    }
    /* mix-blend-mode: the body's own solid color blends over the painted
     * backdrop (kMixBlendCS, with the filter pass). Like backdrop the body
     * paint is skipped and replaced by the blended result - the record
     * carries the single body color (gradients use their first stop;
     * subtree content does not participate, documented). CPU path blends
     * per pixel after children paint (see the tail of paint_node). */
    std::string mbm = sget(n->style, "mix-blend-mode");
    Gradient mbg;
    std::string mbgv = sget(n->style, "background-image");
    if (mbgv.empty()) {
        mbgv = sget(n->style, "background");
    }
    if (!mbm.empty() && mbm != "normal") {
        mb_mode = blend_mode_id(mbm.c_str());
    }
    if (mb_mode >= 0) {
        mb_src = bg_c;
        if (mb_src == 0) {
            /* gradient-only body: approximate with the first stop */
            if (parse_gradient(mbgv, mbg) && !mbg.stops.empty()) {
                mb_src = mbg.stops[0].c;
            }
        }
        if (mb_src != 0) {
            mb_skip_body = true;
            if (g_gpu) {
                whaleui_gpu_mixblend(g_gpu,
                                     static_cast<float>(n->border.x + nox),
                                     static_cast<float>(n->border.y + noy),
                                     static_cast<float>(bw),
                                     static_cast<float>(bh),
                                     static_cast<float>(radius), mb_mode,
                                     mb_src);
            }
        } else {
            mb_mode = -1; /* no body color: plain paint */
        }
    }
    if (bg != 0 && !mb_skip_body) {
        if (has_rot) {
            fill_rot_rect(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                          n->border.y + noy, bw, bh, radius, bg_c, trot, eff,
                          toox * tsx, toooy * tsy, tskx, tsky);
        } else if (radius > 0) {
            fill_round_rect(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                            n->border.y + noy,
                            bw, bh, radius, bg_c, eff);
        } else {
            fill_rect(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                      n->border.y + noy,
                      bw, bh, bg_c, eff);
        }
    }
    Gradient grad;
    std::string bgv = sget(n->style, "background-image");
    if (bgv.empty()) {
        bgv = sget(n->style, "background");
    }
    /* background-blend-mode: the gradient layer blends over the solid
     * background (bg_c, painted above) instead of plain src-over. Only
     * when both layers exist; otherwise normal paint. */
    unsigned int blend_bg = 0;
    int blend_mode = -1;
    if (bg != 0 && parse_gradient(bgv, grad)) {
        std::string bbm = sget(n->style, "background-blend-mode");
        if (!bbm.empty() && bbm != "normal") {
            int mid = blend_mode_id(bbm.c_str());
            if (mid >= 0) {
                blend_bg = bg_c;
                blend_mode = mid;
            }
        }
    }
    if (parse_gradient(bgv, grad)) {
        if (mb_skip_body) {
            /* mix-blend replaces the whole body: skip the gradient too */
        } else {
        if (radius > 0) {
            /* gradients ignore the corner arcs (ponytail: fill the full
             * rect; clipped inside rounded containers already) */
        }
        /* background-size / -position / -repeat: one tile box, then tiled
         * (or a single tile for no-repeat). Absent size -> the whole
         * padding box, which is the common case. */
        float tw = static_cast<float>(bw);
        float th = static_cast<float>(bh);
        std::vector<std::string> sz = split_space2(sget(n->style, "background-size"));
        if (!sz.empty()) {
            if (sz[0] == "cover" || sz[0] == "contain") {
                /* the visible box, not the aspect-true fit: a cover-fit
                 * would need the image's intrinsic size */
                tw = static_cast<float>(bw);
                th = static_cast<float>(bh);
            } else {
                tw = bg_len_px(sz[0], bw);
                th = sz.size() > 1 ? bg_len_px(sz[1], bh) : th;
            }
        }
        if (tw < 1.0f) {
            tw = 1.0f;
        }
        if (th < 1.0f) {
            th = 1.0f;
        }
        float ox = 0, oy = 0;
        std::vector<std::string> ps = split_space2(sget(n->style, "background-position"));
        if (ps.size() == 1) {
            if (ps[0] == "top" || ps[0] == "bottom") {
                oy = bg_pos_px(ps[0], bh, th);
            } else {
                ox = bg_pos_px(ps[0], bw, tw);
            }
        } else if (ps.size() >= 2) {
            ox = bg_pos_px(ps[0], bw, tw);
            oy = bg_pos_px(ps[1], bh, th);
        }
        const int gx = n->border.x + nox;
        const int gy = n->border.y + noy;
        /* clip-path shape mapped onto the gradient tile quad */
        float gct = 0, gccx = 0, gccy = 0, gcr0 = 0, gcr1 = 0, gcrad = 0;
        std::string rpv = sget(n->style, "background-repeat");
        if (rpv.find("no-repeat") != std::string::npos) {
            int txx = gx + static_cast<int>(ox);
            int tyy = gy + static_cast<int>(oy);
            if (!g_clip_stack.empty()) {
                gct = static_cast<float>(clip_for_quad(
                    static_cast<float>(txx), static_cast<float>(tyy), &gccx,
                    &gccy, &gcr0, &gcr1, &gcrad));
            }
            fill_gradient(r->pixels, r->fb_w, r->fb_h, txx, tyy,
                          static_cast<int>(tw), static_cast<int>(th), grad,
                          eff, trot, tskx, tsky, blend_bg, blend_mode, gct,
                          gccx, gccy, gcr0, gcr1, gcrad);
        } else {
            /* repeat (default) / repeat-x / repeat-y: tile from the
             * position back to the box edge, then forward */
            const bool rx = rpv.find("repeat-y") == std::string::npos;
            const bool ry = rpv.find("repeat-x") == std::string::npos;
            int x0 = gx + static_cast<int>(ox);
            int y0 = gy + static_cast<int>(oy);
            if (rx) {
                while (x0 > gx) {
                    x0 -= static_cast<int>(tw);
                }
            }
            if (ry) {
                while (y0 > gy) {
                    y0 -= static_cast<int>(th);
                }
            }
            const int xi = rx ? static_cast<int>(tw) : bw + 1;
            const int yi = ry ? static_cast<int>(th) : bh + 1;
            for (int yy = ry ? y0 : gy + static_cast<int>(oy);
                 yy < gy + bh; yy += yi) {
                for (int xx = rx ? x0 : gx + static_cast<int>(ox);
                     xx < gx + bw; xx += xi) {
                    float tct = 0, tccx = 0, tccy = 0, tcr0 = 0, tcr1 = 0,
                          tcrad = 0;
                    if (!g_clip_stack.empty()) {
                        tct = static_cast<float>(clip_for_quad(
                            static_cast<float>(xx), static_cast<float>(yy),
                            &tccx, &tccy, &tcr0, &tcr1, &tcrad));
                    }
                    fill_gradient(r->pixels, r->fb_w, r->fb_h, xx, yy,
                                  static_cast<int>(tw), static_cast<int>(th),
                                  grad, eff, trot, tskx, tsky, blend_bg,
                                  blend_mode, tct, tccx, tccy, tcr0, tcr1,
                                  tcrad);
                }
            }
        }
        } /* end else (!mb_skip_body): gradient paints normally */
    }
    /* border (follows the corner arcs when border-radius is set).
     * Skipped under mix-blend (the whole body is replaced by the blend). */
    int bw2[4] = {n->border_w[0], n->border_w[1], n->border_w[2], n->border_w[3]};
    bool any = !mb_skip_body &&
               (bw2[0] || bw2[1] || bw2[2] || bw2[3]);
    if (any) {
        unsigned int def_c = color_of(n->style, "border-color",
                                      border_color_of(n->style, 0xFF000000));
        /* per-side colors: several themes set four different sides (aero's
         * bevel inputs, photon's dark bottom edge) - the single-color path
         * flattened them. When they agree, keep the rounded ring path. */
        unsigned int sc[4];
        bool same = true;
        for (int i = 0; i < 4; ++i) {
            sc[i] = border_side_color(n->style, i, def_c);
            if (sc[i] != sc[0]) {
                same = false;
            }
        }
        if (same && sc[0] != 0) {
            unsigned int bc = sc[0];
            unsigned int a = (bc >> 24) & 0xFF;
            unsigned int a8 = static_cast<unsigned>(a * n->opacity);
            unsigned int c = (a8 << 24) | (bc & 0x00FFFFFF);
            int radius = 0;
            std::string br2 = sget(n->style, "border-radius");
            if (!br2.empty()) {
                radius = std::atoi(br2.c_str());
            }
            /* uniform border width for the ring */
            int brw = bw2[1] > 0 ? bw2[1] : (bw2[3] > 0 ? bw2[3] : (bw2[0] > 0 ? bw2[0] : bw2[2]));
            if (has_rot && brw > 0) {
                /* rotated ring: same two-rect trick as fill_round_border's
                 * GPU branch, with rotated corners (the inner refill keeps
                 * the background the ring encloses). The inner rect's
                 * origin shifts by brw, so its in-box anchor shifts too. */
                fill_rot_rect(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                              n->border.y + noy, bw, bh, radius, c, trot, eff,
                              toox * tsx, toooy * tsy, tskx, tsky);
                int irad = radius - brw;
                if (irad < 0) {
                    irad = 0;
                }
                fill_rot_rect(r->pixels, r->fb_w, r->fb_h,
                              n->border.x + nox + brw, n->border.y + noy + brw,
                              bw - 2 * brw, bh - 2 * brw, irad, bg_c, trot,
                              eff, toox * tsx - brw, toooy * tsy - brw,
                              tskx, tsky);
            } else if (radius > 0 && brw > 0) {
                fill_round_border(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                                  n->border.y + noy,
                                  bw, bh, radius, brw, c, bg_c, eff);
            } else {
                if (bw2[0]) { /* top */
                    fill_rect(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                              n->border.y + noy, bw, bw2[0], c, eff);
                }
                if (bw2[2]) { /* bottom */
                    fill_rect(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                              n->border.y + noy + bh - bw2[2], bw, bw2[2], c, eff);
                }
                if (bw2[1]) { /* right */
                    fill_rect(r->pixels, r->fb_w, r->fb_h,
                              n->border.x + nox + bw - bw2[1],
                              n->border.y + noy, bw2[1], bh, c, eff);
                }
                if (bw2[3]) { /* left */
                    fill_rect(r->pixels, r->fb_w, r->fb_h, n->border.x + nox,
                              n->border.y + noy, bw2[3], bh, c, eff);
                }
            }
        } else if (!same) {
            /* four different colors: one fill per side, corner arcs are
             * dropped (a browser miters them; the difference is 1-2px at
             * the corners of a beveled control) */
            const int sx = n->border.x + nox;
            const int sy = n->border.y + noy;
            for (int i = 0; i < 4; ++i) {
                if (!bw2[i] || sc[i] == 0) {
                    continue;
                }
                unsigned int a = (sc[i] >> 24) & 0xFF;
                unsigned int a8 = static_cast<unsigned>(a * n->opacity);
                unsigned int c = (a8 << 24) | (sc[i] & 0x00FFFFFF);
                if (i == 0) {
                    fill_rect(r->pixels, r->fb_w, r->fb_h, sx, sy, bw,
                              bw2[0], c, eff);
                } else if (i == 2) {
                    fill_rect(r->pixels, r->fb_w, r->fb_h, sx,
                              sy + bh - bw2[2], bw, bw2[2], c, eff);
                } else if (i == 1) {
                    fill_rect(r->pixels, r->fb_w, r->fb_h, sx + bw - bw2[1],
                              sy, bw2[1], bh, c, eff);
                } else {
                    fill_rect(r->pixels, r->fb_w, r->fb_h, sx, sy, bw2[3],
                              bh, c, eff);
                }
            }
        }
    }
    if (bdf_gpu) {
        whaleui_gpu_late_end(g_gpu);
    }
    } /* end if(!native_ctrl): native controls paint their own box */
    /* the outline is independent of the box painting (a focus ring must
     * also sit over a native checkbox/select), so it is drawn here - after
     * this element's own content, before its children */
    paint_outline(r, n, nox, noy, bw, bh, eff);
    int child_off_y = noy + scroll_delta(r, n);
    /* chunked child walk: one merged-box test skips WUI_CHUNK siblings at
     * once (a parent with 100k children costs ~1500 tests, not 100k). Chunks
     * only exist for parents built through append_child(); when they are
     * absent (older nodes, reparented subtrees) this degenerates to the plain
     * `next` walk. */
    whaleui_child_chunk* ck = n->chunks;
    for (whaleui_layout_node_t* c = n->first_child; c;) {
        if (ck && c->chunk == ck) {
            const whaleui_child_chunk* cur = ck;
            ck = ck->next;
            if (chunk_culled(cur, nox, child_off_y, eff)) {
                c = cur->last ? cur->last->next : nullptr;
                continue;
            }
        }
        paint_node(r, c, nox, child_off_y, seq, sel_lo, sel_hi, eff, tc);
        c = c->next;
    }
    /* scrollbar sits on top of the content */
    if (n->scroll_max > 0) {
        paint_scrollbar(r, n, nox, noy, eff);
    }
    /* native controls drawn by the engine (not editable): checkbox/radio
     * boxes and progress/meter tracks. tag_id pre-filters before the
     * attribute checks. Pseudo-element boxes share el with their owner but
     * must not trigger the owner's control painting (an input's ::after
     * focus underline is a plain painted box). */
    if (kind == kCtrlCheckRadio) {
        paint_checkbox(r, n, nox, noy, eff);
    } else if (kind == kCtrlProgress) {
        paint_progress(r, n, nox, noy, eff);
    } else if (kind == kCtrlEditable) {
        paint_editable(r, n, nox, noy, eff);
    }
    /* <select> control: value + arrow painted here; the expanded list is
     * painted LAST in render_frame so nothing occludes it. Pseudo-element
     * boxes (the focus underline) share el with the select but must not
     * trigger the value paint - its transform (scaleX) shifts nox and
     * drew a second offset value+arrow. */
    if (kind == kCtrlSelect) {
        paint_select_value(r, n, nox, noy, eff);
    }
    /* CPU filter: the 4x5 color matrix over this element's painted box
     * (body + children above - everything this call painted). GPU path
     * handles it in pass E instead (this would double-apply). Blur is
     * GPU-only. */
    if (has_filter && !g_gpu) {
        int fx = n->border.x + nox;
        int fy = n->border.y + noy;
        int x0 = fx < 0 ? 0 : fx;
        int y0 = fy < 0 ? 0 : fy;
        int x1 = fx + bw > r->fb_w ? r->fb_w : fx + bw;
        int y1 = fy + bh > r->fb_h ? r->fb_h : fy + bh;
        clip_rect(x0, y0, x1, y1, eff);
        for (int yy = y0; yy < y1; ++yy) {
            for (int xx = x0; xx < x1; ++xx) {
                unsigned int& d = r->pixels[static_cast<size_t>(yy) * r->fb_w + xx];
                float fr = ((d >> 16) & 0xFF) / 255.0f;
                float fg = ((d >> 8) & 0xFF) / 255.0f;
                float fb = (d & 0xFF) / 255.0f;
                float fa = ((d >> 24) & 0xFF) / 255.0f;
                float or_ = filter_m[0][0] * fr + filter_m[0][1] * fg +
                            filter_m[0][2] * fb + filter_m[0][3] * fa +
                            filter_m[0][4];
                float og = filter_m[1][0] * fr + filter_m[1][1] * fg +
                           filter_m[1][2] * fb + filter_m[1][3] * fa +
                           filter_m[1][4];
                float ob = filter_m[2][0] * fr + filter_m[2][1] * fg +
                           filter_m[2][2] * fb + filter_m[2][3] * fa +
                           filter_m[2][4];
                float oa = filter_m[3][0] * fr + filter_m[3][1] * fg +
                           filter_m[3][2] * fb + filter_m[3][3] * fa +
                           filter_m[3][4];
                if (or_ < 0) {
                    or_ = 0;
                } else if (or_ > 1) {
                    or_ = 1;
                }
                if (og < 0) {
                    og = 0;
                } else if (og > 1) {
                    og = 1;
                }
                if (ob < 0) {
                    ob = 0;
                } else if (ob > 1) {
                    ob = 1;
                }
                if (oa < 0) {
                    oa = 0;
                } else if (oa > 1) {
                    oa = 1;
                }
                d = (static_cast<unsigned int>(oa * 255 + 0.5f) << 24) |
                    (static_cast<unsigned int>(or_ * 255 + 0.5f) << 16) |
                    (static_cast<unsigned int>(og * 255 + 0.5f) << 8) |
                    static_cast<unsigned int>(ob * 255 + 0.5f);
            }
        }
    }
    /* CPU mix-blend: the recorded body color over the painted backdrop.
     * GPU path handles it in pass F instead. */
    if (mb_mode >= 0 && !g_gpu) {
        int fx = n->border.x + nox;
        int fy = n->border.y + noy;
        int x0 = fx < 0 ? 0 : fx;
        int y0 = fy < 0 ? 0 : fy;
        int x1 = fx + bw > r->fb_w ? r->fb_w : fx + bw;
        int y1 = fy + bh > r->fb_h ? r->fb_h : fy + bh;
        clip_rect(x0, y0, x1, y1, eff);
        for (int yy = y0; yy < y1; ++yy) {
            for (int xx = x0; xx < x1; ++xx) {
                unsigned int& d = r->pixels[static_cast<size_t>(yy) * r->fb_w + xx];
                d = blend_pixels(d, mb_src, mb_mode);
            }
        }
    }
    if (pushed_mask && !g_mask_stack.empty()) {
        g_mask_stack.pop_back();
    }
    if (pushed_clip && !g_clip_stack.empty()) {
        g_clip_stack.pop_back();
    }
}
